#!/usr/bin/env node
/**
 * Builds the client-side search index for the API reference.
 *
 * Input:  ../api/reference/*.api.mdx — the per-endpoint pages generated by
 *         `docusaurus gen-api-docs` (npm run build:openapi:docs).
 * Output: data/api-search-index.json — consumed by src/components/ApiSearch.
 *
 * Why read the generated MDX rather than the OpenAPI spec itself: the MDX
 * frontmatter is the only place where the endpoint's method/path and the
 * *doc id* that its page is published under live side by side. Deriving the
 * doc id from the spec would mean re-implementing the plugin's operationId →
 * slug logic, which would silently drift the moment the plugin changes it.
 *
 * The `api:` frontmatter value is a zlib-deflated, base64-encoded JSON blob
 * (docusaurus-plugin-openapi-docs compresses it so the operation object can
 * ride along in frontmatter). Inflating it is the documented round-trip —
 * see the commented-out helpers in
 * node_modules/docusaurus-plugin-openapi-docs/lib/index.js.
 *
 * Usage:  node scripts/gen-api-search-index.mjs   (from docs/site/)
 */

import {inflateSync} from 'node:zlib';
import {readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {parse} from 'yaml';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url)); // docs/site/scripts
const DOCS_SITE_DIR = resolve(SCRIPT_DIR, '..'); // docs/site
const REFERENCE_DIR = resolve(DOCS_SITE_DIR, '../api/reference'); // docs/api/reference
const OUTPUT_PATH = resolve(DOCS_SITE_DIR, 'data/api-search-index.json');

// Doc ids in the generated sidebar are prefixed with the directory the pages
// live in, relative to the `api` docs plugin's `path` (docs/api). The plugin
// mounts that instance at routeBasePath '/api', so the page URL is
// `/api/<docId>` — see docusaurus.config.ts.
const DOC_ID_PREFIX = 'reference/';

// Generated pages always open with a `---` fence on line 1 and close it on a
// line of its own; the body starts after that.
const FRONT_MATTER = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/;

/** Parses a generated page's YAML frontmatter; throws if the block is absent. */
function frontMatterOf(source, file) {
  const match = FRONT_MATTER.exec(source);
  if (!match) {
    throw new Error(`${file}: no frontmatter block`);
  }
  return parse(match[1]);
}

/**
 * Decodes the OpenAPI operation object out of a page's `api` frontmatter,
 * or returns undefined when the page carries none.
 */
function operationOf(frontMatter, file) {
  // `api` is absent on the info/tag pages, which this script never reads, and
  // on operations the plugin failed to serialize — skip those rather than
  // failing the whole build.
  if (typeof frontMatter.api !== 'string') {
    return undefined;
  }
  try {
    return JSON.parse(inflateSync(Buffer.from(frontMatter.api, 'base64')).toString());
  } catch (err) {
    console.warn(`[api-search] ${file}: could not decode api frontmatter (${err.message})`);
    return undefined;
  }
}

/** Reads every generated endpoint page and writes the search index. */
function main() {
  if (!existsSync(REFERENCE_DIR)) {
    console.error(`[api-search] generated API reference not found at ${REFERENCE_DIR}`);
    console.error('[api-search] Run `npm run build:openapi:docs` first.');
    process.exit(1);
  }

  const files = readdirSync(REFERENCE_DIR)
    .filter((name) => name.endsWith('.api.mdx'))
    .sort();

  const endpoints = [];
  let skipped = 0;

  for (const file of files) {
    const frontMatter = frontMatterOf(readFileSync(join(REFERENCE_DIR, file), 'utf8'), file);
    const operation = operationOf(frontMatter, file);

    if (!operation?.method || !operation?.path || !frontMatter.id) {
      skipped++;
      continue;
    }

    endpoints.push({
      id: DOC_ID_PREFIX + frontMatter.id,
      method: operation.method.toUpperCase(),
      path: operation.path,
      // `title` is the operation summary; it's what the sidebar shows as the
      // endpoint's label, so searching it matches what readers see.
      title: frontMatter.title ?? frontMatter.id,
      // Only the first tag is meaningful — the plugin groups an operation
      // under its first tag, so that's the sidebar category it appears in.
      tag: operation.tags?.[0] ?? '',
      ...(operation.deprecated ? {deprecated: true} : {}),
    });
  }

  // Stable order (method within path) so the JSON diff stays readable and
  // results for equally-scoring matches don't shuffle between builds.
  endpoints.sort((a, b) => a.path.localeCompare(b.path) || a.method.localeCompare(b.method));

  mkdirSync(dirname(OUTPUT_PATH), {recursive: true});
  writeFileSync(OUTPUT_PATH, `${JSON.stringify({endpoints}, null, 0)}\n`);

  const sizeKb = (readFileSync(OUTPUT_PATH).length / 1024).toFixed(1);
  console.log(
    `[api-search] Indexed ${endpoints.length} endpoints (${skipped} page(s) without an operation) → ${sizeKb} KB`,
  );
}

main();
